-- Owner-approved annual catalog, 18 November 2026. Data only; preserve plan IDs, account links and contract snapshots.
begin;
lock table public.crm_plans in share row exclusive mode;
do $guard$ begin
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"أساس","description":"بداية مرتّبة لناديك","pricing_type":"fixed","annual_fee_cents":360000,"setup_fee_cents":0,"features":["فرع واحد","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","سجلات التحصيل والفواتير","صلاحيات فريق العمل","التقارير الأساسية"],"active":true,"sort_order":1,"revision":0}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"تشغيل","description":"للنادي الذي يقدم أكثر","pricing_type":"fixed","annual_fee_cents":720000,"setup_fee_cents":0,"features":["فرع واحد","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","سجلات التحصيل والفواتير","صلاحيات فريق العمل","التقارير الأساسية","نقاط البيع وإدارة الورديات","المطبخ وقوائم الوجبات اليومية","اشتراكات الوجبات وصرفها","مخزون المنتجات والمرتجعات","تقارير المبيعات والتشغيل"],"active":true,"sort_order":2,"revision":0}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"توسّع","description":"منظومة تنمو مع طموحك","pricing_type":"fixed","annual_fee_cents":1200000,"setup_fee_cents":0,"features":["حتى ٣ فروع","إدارة الأعضاء والاشتراكات","التجديد والتجميد ومتابعة الحضور","سجلات التحصيل والفواتير","صلاحيات فريق العمل","التقارير الأساسية","نقاط البيع وإدارة الورديات","المطبخ وقوائم الوجبات اليومية","اشتراكات الوجبات وصرفها","مخزون المنتجات والمرتجعات","تقارير المبيعات والتشغيل","حجوزات الملاعب والحصص","مواعيد التدريب الشخصي","إدارة مركزية للفروع","صلاحيات وتشغيل حسب الفرع","تقارير مجمّعة لمتابعة الأداء"],"active":true,"sort_order":3,"revision":0}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"الشراكة التقنية","description":"عرض مخصص حسب نطاق المنصة والتطوير والتكامل المتفق عليه.","pricing_type":"custom","annual_fee_cents":null,"setup_fee_cents":0,"features":["اشتراك المنصة بالنطاق المتفق عليه","دراسة تطبيق خاص للأعضاء","دراسة تكامل بوابات الدخول المتوافقة","ربط أنظمة خارجية أو تطوير مخصص","تحديد التنفيذ والأجهزة والصيانة في عرض مستقل"],"active":true,"sort_order":4,"revision":0}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if exists(select 1 from public.crm_plans where lower(btrim(name)) in ('متكاملة','شراكة تقنية')) then raise exception 'New plan name already exists; review before applying'; end if;
end $guard$;
update public.crm_plans set description='بداية مرتّبة لناديك', annual_fee_cents=180000, features=array['فرع واحد','إدارة الأعضاء والاشتراكات','التجديد والتجميد ومتابعة الحضور','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','صلاحيات فريق العمل','التقارير الأساسية']::text[],sort_order=1 where name='أساس';
update public.crm_plans set description='للحجوزات والتدريب اليومي', annual_fee_cents=330000, features=array['فرع واحد','إدارة الأعضاء والاشتراكات','التجديد والتجميد ومتابعة الحضور','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','صلاحيات فريق العمل','التقارير الأساسية','حجوزات الملاعب والحصص','مواعيد التدريب الشخصي','إدارة المدربين والقياسات','الخطط والبرامج التدريبية','جداول ودوام الموظفين']::text[],sort_order=2 where name='تشغيل';
insert into public.crm_plans(name,description,annual_fee_cents,features,sort_order) values('متكاملة','لربط المبيعات والمخزون والوجبات',420000,array['فرع واحد','إدارة الأعضاء والاشتراكات','التجديد والتجميد ومتابعة الحضور','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','صلاحيات فريق العمل','التقارير الأساسية','حجوزات الملاعب والحصص','مواعيد التدريب الشخصي','إدارة المدربين والقياسات','الخطط والبرامج التدريبية','جداول ودوام الموظفين','المنتجات ومخزونها والمرتجعات','المطبخ وقوائم الوجبات اليومية','اشتراكات الوجبات وصرفها','تقارير المبيعات والتشغيل']::text[],3);
update public.crm_plans set description='منظومة تنمو مع طموحك', annual_fee_cents=660000, features=array['فرعان','إدارة الأعضاء والاشتراكات','التجديد والتجميد ومتابعة الحضور','نقاط البيع وورديات الصندوق','الفواتير والتحصيل والمرتجعات','صلاحيات فريق العمل','التقارير الأساسية','حجوزات الملاعب والحصص','مواعيد التدريب الشخصي','إدارة المدربين والقياسات','الخطط والبرامج التدريبية','جداول ودوام الموظفين','المنتجات ومخزونها والمرتجعات','المطبخ وقوائم الوجبات اليومية','اشتراكات الوجبات وصرفها','تقارير المبيعات والتشغيل','إدارة مركزية للفروع','صلاحيات وتشغيل حسب الفرع','تقارير مجمّعة لمتابعة الأداء']::text[],sort_order=4 where name='توسّع';
update public.crm_plans set name='شراكة تقنية',description='لثلاثة فروع فأكثر أو احتياجات تقنية خاصة، بعرض سعر مخصص دون اشتراط تطوير.',features=array['اشتراك المنصة لثلاثة فروع فأكثر أو احتياج تقني خاص','نقاط البيع وورديات الصندوق ضمن نطاق المنصة','تحديد وظائف المنصة والتهيئة ونقل البيانات والتدريب والدعم في العرض','يمكن أن يقتصر الاتفاق على اشتراك المنصة للفروع','التطبيقات والتكاملات والتطوير اختيارية وتُسعّر منفصلة','تحديد الأجهزة ورسوم الأطراف الأخرى والصيانة بشكل مستقل']::text[],sort_order=5 where name='الشراكة التقنية';
commit;
